'use client';

import * as React from 'react';
import { Checkbox } from '@base-ui/react/checkbox';
import './cue.css';

/* ─────────────────────────────────────────────────────────
 * CUE FAMILY (Kamui 03 §3, the medium demo)
 *
 * A cue is a rendering attribute on the text, never a change to it.
 *   in-flow   date · duration · amount · measurement · tag · derived tag · hex
 *             metric-neutral: width delta 0.00 pt, so a cue appearing mid-word never moves a letter
 *   hover     the resolved value rises 3 over the cue on the part spring (data-chip)
 *   at rest   a URL becomes a host pill; a value Jev read that is not in the text is an inferred pill
 *   margin    the dimple (a task's checkbox), the ghost dimple (a task Jev inferred), the urgency LED
 *   trailing  the life glyph after a middle dot, ink3 → ink2 with its host
 *   tick      draws on in 220 ms after 40 ms, ease-out, not sprung (DS-21); instant under Reduce Motion
 * ───────────────────────────────────────────────────────── */

export type CueKind = 'date' | 'duration' | 'amount' | 'measurement' | 'tag' | 'derived-tag' | 'hex';

export interface CueProps extends React.HTMLAttributes<HTMLSpanElement> {
  kind: CueKind;
  /** The resolved value, shown on hover as a graphite chip: "TUE 30 SEP · 16:00", "1 H 30 · 90 MIN". */
  resolved?: string;
  /** For hex: the colour the text names. The underline and swatch take it. */
  color?: string;
  /** For hex: show the 11 pt swatch before the text (display only, never while writing). */
  swatch?: boolean;
}

/** An in-flow cue on recognised text. Metric-neutral: the words keep their exact advance. */
export const Cue = React.forwardRef<HTMLSpanElement, CueProps>(function Cue({ kind, resolved, color, swatch, className, style, children, ...props }, ref) {
  return (
    <span
      ref={ref}
      data-kind={kind}
      data-chip={resolved}
      className={className ? `mu-cue ${className}` : 'mu-cue'}
      style={color ? ({ '--mu-cue-hex': color, ...style } as React.CSSProperties) : style}
      {...props}
    >
      {kind === 'hex' && swatch && <i aria-hidden className="mu-cue-swatch" />}
      {children}
    </span>
  );
});

export interface CueUrlProps extends React.AnchorHTMLAttributes<HTMLAnchorElement> {
  /** The host the pill shows at rest: "figma.com". */
  host: string;
  /** The glyph before the host, at 11: pass the set's link glyph, e.g. <LinkIcon size={11} />. */
  glyph?: React.ReactNode;
}

/** A URL at rest: a short host pill. While writing, show the raw URL as plain text instead. */
export const CueUrl = React.forwardRef<HTMLAnchorElement, CueUrlProps>(function CueUrl({ host, glyph, className, ...props }, ref) {
  return (
    <a ref={ref} target="_blank" rel="noopener noreferrer" className={className ? `mu-cue-url type-ui ${className}` : 'mu-cue-url type-ui'} {...props}>
      {glyph}
      {host}
    </a>
  );
});

export interface CueInferredProps extends React.HTMLAttributes<HTMLSpanElement> {
  /** The value and where it came from, on hover: "TUE 30 SEP · JEV 0.82". */
  resolved?: string;
}

/** A value Jev read that is not in the text (a date, a measurement): a hollow pill after the words. */
export const CueInferred = React.forwardRef<HTMLSpanElement, CueInferredProps>(function CueInferred({ resolved, className, ...props }, ref) {
  return <span ref={ref} data-chip={resolved} className={['mu-cue', 'mu-cue-inferred', 'mu-type-label', className].filter(Boolean).join(' ')} {...props} />;
});

export interface DimpleProps extends Omit<Checkbox.Root.Props, 'className' | 'indeterminate'> {
  /** The task is in progress: a half-filled green square (announced as mixed). */
  doing?: boolean;
  /** A task Jev inferred and nobody wrote: the hollow ghost dimple, hanging in the margin. */
  ghost?: boolean;
  className?: string;
}

/**
 * A task's checkbox: a 16 pt well in the margin (Base UI Checkbox). Checked, it turns dark and the
 * tick draws on. Ticking it is a person's action: the host writes `[x]` into the text, with Undo.
 */
export const Dimple = React.forwardRef<HTMLButtonElement, DimpleProps>(function Dimple({ doing, ghost, className, ...props }, ref) {
  // The slot carries placement (the margin at −25): Base UI renders a hidden form input beside the
  // checkbox, and the slot keeps both out of the line's flow.
  return (
    <span className={className ? `mu-dimple-slot ${className}` : 'mu-dimple-slot'}>
      <Checkbox.Root
        ref={ref}
        indeterminate={doing && !props.checked ? true : undefined}
        data-ghost={ghost ? '' : undefined}
        className="mu-dimple"
        {...props}
      >
        <Checkbox.Indicator render={(p, state) => (state.checked ? <span {...p} className="mu-dimple-tick" /> : <span {...p} hidden />)} />
      </Checkbox.Root>
    </span>
  );
});

/** Urgency: a 5 pt amber LED in the margin of an open task that is due soon. */
export function CueUrgency({ className, ...props }: React.HTMLAttributes<HTMLSpanElement>) {
  return <span role="img" aria-label="Due soon" className={className ? `mu-cue-urgency ${className}` : 'mu-cue-urgency'} {...props} />;
}

export interface CueLifeProps extends React.HTMLAttributes<HTMLSpanElement> {
  /** The glyph at 16, e.g. <LifeCoffeeIcon size={16} /> from @unlocalhosted/metalui/icons/life. */
  children: React.ReactNode;
}

/** The life glyph trailing a block: a middle dot, then the glyph. Display only: never while writing. */
export function CueLife({ children, className, ...props }: CueLifeProps) {
  return (
    <span className={className ? `mu-cue-life ${className}` : 'mu-cue-life'} {...props}>
      <span aria-hidden className="mu-cue-md">·</span>
      <span className="mu-cue-lg">{children}</span>
    </span>
  );
}

@import "../tokens.css";

/* The cue family (Kamui 03 §3, the medium demo). Every value is --mu-cue-* or a colorway cue-* token.
   In-flow cues are metric-neutral: they never change the advance of the text they mark. That rules out
   tabular numerals in flow: Geist's tabular digits are wider than its proportional ones (the demo's
   tabular-nums moved a 1h30 · $40 · 6h line by 1.09 px), so values keep the text's own figures. */

/* ---- in-flow text cues ---- */
.mu-cue { position: relative; }
.mu-cue[data-kind="date"] {
  text-decoration: underline dotted var(--mu-cue-date-underline);
  text-decoration-thickness: var(--mu-cue-date-thickness);
  text-underline-offset: var(--mu-cue-underline-offset);
}
.mu-cue:is([data-kind="duration"], [data-kind="amount"]) {
  text-decoration: underline solid var(--mu-cue-quiet);
  text-decoration-thickness: var(--mu-cue-quiet-thickness);
  text-underline-offset: var(--mu-cue-underline-offset);
}
.mu-cue[data-kind="measurement"] {
  text-decoration: underline solid var(--mu-cue-measure-underline);
  text-decoration-thickness: var(--mu-cue-measure-thickness);
  text-underline-offset: var(--mu-cue-measure-offset);
}
/* Tag: a soft pill whose padding is paid back by an equal negative margin, so the words do not move. */
.mu-cue:is([data-kind="tag"], [data-kind="derived-tag"]) {
  padding: var(--mu-cue-tag-pad-y) var(--mu-cue-tag-pad-x);
  margin: 0 calc(var(--mu-cue-tag-pad-x) * -1);
  border-radius: 999px;
  color: var(--mu-ink2);
  -webkit-box-decoration-break: clone;
  box-decoration-break: clone;
  background: var(--mu-cue-tag-bg);
  box-shadow: var(--mu-cue-tag-sh);
}
.mu-cue[data-kind="derived-tag"] { background: transparent; box-shadow: var(--mu-cue-derived-sh); color: var(--mu-ink3); }
.mu-cue[data-kind="hex"] {
  text-decoration: underline solid color-mix(in srgb, var(--mu-cue-hex, var(--mu-ink3)) var(--mu-cue-hex-mix), transparent);
  text-decoration-thickness: var(--mu-cue-hex-thickness);
  text-underline-offset: var(--mu-cue-hex-offset);
  text-decoration-skip-ink: none;
}
.mu-cue-swatch {
  display: inline-block;
  width: var(--mu-cue-swatch);
  height: var(--mu-cue-swatch);
  border-radius: var(--mu-cue-swatch-radius);
  transform: translateY(1px);
  background: var(--mu-cue-hex);
  box-shadow: var(--mu-cue-swatch-sh);
}

/* The resolved value, on hover: a graphite chip rising 3 over the cue on the part spring. Absolute, so metric-neutral. */
.mu-cue[data-chip]:hover::after,
.mu-cue[data-chip]:focus-visible::after {
  content: attr(data-chip);
  position: absolute;
  left: 50%;
  bottom: calc(100% + var(--mu-cue-chip-gap));
  transform: translateX(-50%);
  padding: var(--mu-cue-chip-pad-y) var(--mu-cue-chip-pad-x);
  border-radius: 999px;
  white-space: nowrap;
  pointer-events: none;
  z-index: 30;
  font: var(--mu-type-label);
  font-stretch: var(--mu-mono-stretch);
  letter-spacing: var(--mu-type-label-tracking);
  text-transform: uppercase;
  text-decoration: none;
  color: var(--mu-cue-chip-ink);
  background: var(--mu-frost-graphite-fill);
  box-shadow: var(--mu-frost-graphite-shadow);
  animation: mu-cue-chip var(--mu-spring-part-d) var(--mu-spring-part) both;
}
@keyframes mu-cue-chip {
  from { opacity: 0; transform: translate(-50%, calc(var(--mu-cue-chip-rise) * var(--mu-travel-part))); }
}

/* ---- the URL host pill (at rest; while writing the raw URL shows as plain text) ---- */
.mu-cue-url {
  display: inline-flex;
  align-items: center;
  gap: var(--mu-cue-url-gap);
  height: var(--mu-cue-url-height);
  padding: 0 var(--mu-cue-url-pad-end) 0 var(--mu-cue-url-pad-start);
  border-radius: 999px;
  vertical-align: 1px;
  color: var(--mu-cue-url-ink);
  text-decoration: none;
  background: var(--mu-cue-url-bg);
  box-shadow: var(--mu-cue-url-ring);
  transition: background var(--mu-spring-settle-d) var(--mu-spring-settle);
}
.mu-cue-url:hover { background: var(--mu-cue-url-bg-hover); }
.mu-cue-url > svg { width: var(--mu-cue-url-glyph); height: var(--mu-cue-url-glyph); }
.mu-cue-url:focus-visible { outline: var(--mu-focus-width) solid var(--mu-focus); outline-offset: var(--mu-focus-offset); }

/* ---- the inferred pill: a value Jev read that is not in the text (a date, a measurement) ---- */
.mu-cue-inferred {
  position: relative;
  display: inline-block;
  margin-left: var(--mu-cue-inferred-gap);
  padding: 0 var(--mu-cue-inferred-pad);
  height: var(--mu-cue-inferred-height);
  border-radius: 999px;
  vertical-align: 1px;
  line-height: var(--mu-cue-inferred-height);
  color: var(--mu-ink3);
  box-shadow: var(--mu-cue-inferred-ring);
}

/* ---- the dimple: a task's checkbox, a well in the margin ---- */
.mu-dimple-slot { display: inline-flex; width: max-content; height: max-content; line-height: 0; }
.mu-dimple {
  position: relative;
  box-sizing: border-box;
  display: inline-block;
  width: var(--mu-cue-dimple);
  height: var(--mu-cue-dimple);
  padding: 0;
  border: 0;
  border-radius: var(--mu-radius-key);
  cursor: pointer;
  background: linear-gradient(var(--mu-well-top), var(--mu-well-bot));
  box-shadow: var(--mu-well);
  transition: background var(--mu-spring-settle-d) var(--mu-spring-settle), box-shadow var(--mu-spring-settle-d) var(--mu-spring-settle);
  -webkit-tap-highlight-color: transparent;
}
.mu-dimple:hover:not([data-checked]) {
  background: linear-gradient(color-mix(in srgb, var(--mu-well-top), var(--mu-ink) 3%), color-mix(in srgb, var(--mu-well-bot), var(--mu-ink) 3%));
}
.mu-dimple[data-checked] { background: var(--mu-cue-dimple-on-bg); box-shadow: var(--mu-cue-dimple-on-sh); }
.mu-dimple:focus-visible { outline: var(--mu-focus-width) solid var(--mu-focus); outline-offset: var(--mu-focus-offset); }
.mu-dimple[data-disabled] { opacity: .4; cursor: default; }
/* The tick draws on with an ease-out after a short beat: not sprung (DS-21). */
.mu-dimple-tick {
  position: absolute;
  left: 5px;
  top: 2.5px;
  width: 4px;
  height: 8px;
  border: solid var(--mu-cue-tick);
  border-width: 0 var(--mu-cue-tick-width) var(--mu-cue-tick-width) 0;
  transform: rotate(42deg);
  animation: mu-dimple-tick var(--mu-cue-tick-ms) var(--mu-cue-tick-delay-ms) var(--mu-ease-slide) both;
}
@keyframes mu-dimple-tick { from { clip-path: inset(0 100% 100% 0); } to { clip-path: inset(0 0 0 0); } }
@media (prefers-reduced-motion: reduce) { .mu-dimple-tick { animation: none; } }
[data-mu-motion="reduce"] .mu-dimple-tick { animation: none; }
/* Doing: a half-filled green square. */
.mu-dimple[data-indeterminate]::before {
  content: "";
  position: absolute;
  inset: var(--mu-cue-doing-inset);
  border-radius: var(--mu-cue-doing-radius);
  background: linear-gradient(90deg, var(--mu-green-deep) 50%, transparent 50%);
  opacity: var(--mu-cue-doing-opacity);
}
/* Ghost: a task Jev inferred, not written. Hangs in the margin; the band grows left instead of the words moving. */
.mu-dimple[data-ghost] {
  width: var(--mu-cue-ghost);
  height: var(--mu-cue-ghost);
  border-radius: var(--mu-cue-ghost-radius);
  background: transparent;
  box-shadow: var(--mu-cue-ghost-sh);
}
.mu-dimple[data-ghost]:hover { background: transparent; box-shadow: inset 0 0 0 1px var(--mu-cue-ghost-hover); }

/* ---- urgency: a 5 pt amber LED in the margin ---- */
.mu-cue-urgency {
  display: inline-block;
  width: var(--mu-cue-urgency-led);
  height: var(--mu-cue-urgency-led);
  border-radius: 50%;
  background: var(--mu-led-amber);
  box-shadow: var(--mu-led-ring);
}

/* ---- the life glyph on a line: after a middle dot, ink3 at rest, ink2 when the host is hovered ---- */
.mu-cue-life { white-space: nowrap; }
.mu-cue-life > .mu-cue-md { color: var(--mu-ink3); margin: 0 var(--mu-cue-life-gap-after) 0 var(--mu-cue-life-gap-before); }
.mu-cue-life > .mu-cue-lg {
  display: inline-block;
  vertical-align: var(--mu-cue-life-drop);
  color: var(--mu-ink3);
  transition: color var(--mu-spring-settle-d) var(--mu-spring-settle);
  animation: mu-cue-life var(--mu-cue-life-ms) var(--mu-ease-slide) both;
}
.mu-cue-life > .mu-cue-lg > svg { display: block; }
.mu-icon-trigger:hover .mu-cue-life > .mu-cue-lg:not(:has([class*="mu-tint-"])) { color: var(--mu-ink2); }
@keyframes mu-cue-life { from { opacity: 0; } }
